sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  if (gs.getProperty('x_ssa_day2_ops.test_mode', 'false') !== 'true') {
    stepResult.setFailed('x_ssa_day2_ops.test_mode must be true — refusing to run against a live tenant');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var gate = new x_ssa_day2_ops.EntraHelpdeskGate();
  var verdict = gate.preflight({
    requester_id: gs.getUser().getID(),
    approver_id: 'day2-servicedesk-sysid',
    privileged: false
  });
  verdict.ok ? stepResult.setSuccess()
             : stepResult.setFailed('preflight should pass for a well-formed request: ' + verdict.reason);
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var client = new x_ssa_day2_ops.EntraHelpdeskClient();
  var res = client.resetPassword('test-user-0001', {});
  if (!res || !res.ok) { stepResult.setFailed('resetPassword did not report ok in test_mode'); return; }
  if (res.action !== 'password-reset') { stepResult.setFailed('unexpected actuation result: ' + JSON.stringify(res)); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

table = sc_req_item
conditions = sys_id={RITM from step 200}
assert = state == 3 (Closed Complete) AND work_notes CONTAINS the evidence/attestation reference
